def get_level_words(level_id: str):
    return CEFR_LEVELS.get(level_id, {}).get("words", [])


def get_all_words():
    result = []
    for lid, lv in CEFR_LEVELS.items():
        for w in lv["words"]:
            result.append({**w, "_level": lid})
    return result


def get_total_count():
    return sum(len(lv["words"]) for lv in CEFR_LEVELS.values())
